// Email suppression shared by all mail workers on one machine.
//
// State lives in an append-only log inside STATE_DIR. Every worker appends to
// the same file with O_APPEND and fsyncs before returning, so an unsubscribe
// survives a kill. Each worker reads only the bytes it has not yet seen, and
// the newest event per address decides the outcome.

import { randomUUID } from "node:crypto";
import { mkdir, open, stat } from "node:fs/promises";
import { join } from "node:path";

const LOG_NAME = "suppression.log";
const KINDS = new Set(["marketing", "receipt"]);

// Per-process read cache. The log only grows, so `offset` marks the end of
// the last fully read line.
let cache = { ino: null, offset: 0, state: new Map() };

function stateDir() {
  const dir = process.env.STATE_DIR;
  if (!dir) throw new Error("STATE_DIR environment variable is not set");
  return dir;
}

// Lowercase and trim. Returns null when the value is not usable as an address.
function normalizeEmail(email) {
  if (typeof email !== "string") return null;
  const e = email.trim().toLowerCase();
  const at = e.indexOf("@");
  if (at < 1 || at === e.length - 1 || e.includes(" ")) return null;
  return e;
}

function requireEmail(email) {
  const e = normalizeEmail(email);
  if (e === null) throw new TypeError(`not a valid email address: ${JSON.stringify(email)}`);
  return e;
}

async function appendEvent(event) {
  const dir = stateDir();
  await mkdir(dir, { recursive: true });
  const fh = await open(join(dir, LOG_NAME), "a");
  try {
    const buf = Buffer.from(JSON.stringify(event) + "\n", "utf8");
    let off = 0;
    while (off < buf.length) {
      const { bytesWritten } = await fh.write(buf, off, buf.length - off);
      off += bytesWritten;
    }
    await fh.sync();
  } finally {
    await fh.close();
  }
}

async function readRange(file, start, length) {
  const fh = await open(file, "r");
  try {
    const buf = Buffer.alloc(length);
    let got = 0;
    while (got < length) {
      const { bytesRead } = await fh.read(buf, got, length - got, start + got);
      if (bytesRead === 0) break;
      got += bytesRead;
    }
    return buf.subarray(0, got);
  } finally {
    await fh.close();
  }
}

// Returns Map<email, { op, at }> holding the newest event per address.
async function loadState() {
  const dir = stateDir();
  await mkdir(dir, { recursive: true });
  const file = join(dir, LOG_NAME);

  let st;
  try {
    st = await stat(file);
  } catch (err) {
    if (err.code === "ENOENT") return new Map();
    throw err;
  }

  // Replaced or truncated file: start over.
  if (cache.ino !== st.ino || st.size < cache.offset) {
    cache = { ino: st.ino, offset: 0, state: new Map() };
  }
  if (st.size === cache.offset) return cache.state;

  const bytes = await readRange(file, cache.offset, st.size - cache.offset);
  const text = bytes.toString("utf8");
  // Ignore a trailing partial line: another worker is still writing it.
  const lastNl = text.lastIndexOf("\n");
  if (lastNl < 0) return cache.state;

  const complete = text.slice(0, lastNl + 1);
  for (const line of complete.split("\n")) {
    if (line === "") continue;
    let ev;
    try {
      ev = JSON.parse(line);
    } catch {
      // Fail closed: skipping a corrupt unsubscribe could mail someone who opted out.
      throw new Error(`corrupt line in ${file}; refusing to send until it is repaired`);
    }
    cache.state.set(ev.email, { op: ev.op, at: ev.at });
  }
  cache.offset += Buffer.byteLength(complete, "utf8");
  return cache.state;
}

export async function unsubscribe(email) {
  const e = requireEmail(email);
  await appendEvent({
    v: 1,
    op: "unsubscribe",
    email: e,
    at: new Date().toISOString(),
    id: randomUUID(),
  });
}

// Call only when the person deliberately signs up again on the website.
export async function resubscribe(email) {
  const e = requireEmail(email);
  await appendEvent({
    v: 1,
    op: "resubscribe",
    email: e,
    at: new Date().toISOString(),
    id: randomUUID(),
  });
}

export async function mayEmail(email, kind, now) {
  if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
    throw new TypeError("now must be a valid Date");
  }
  if (!KINDS.has(kind)) {
    return {
      allowed: false,
      reason: `Unknown email kind ${JSON.stringify(kind)}; use "marketing" or "receipt".`,
    };
  }
  const e = normalizeEmail(email);
  if (e === null) {
    return {
      allowed: false,
      reason: "The address is missing or not a valid email address, so nothing was sent.",
    };
  }

  // Receipts (order confirmations, shipping, password reset) are transactional.
  // A marketing opt-out does not block them under CAN-SPAM or GDPR.
  if (kind === "receipt") {
    return {
      allowed: true,
      reason: "Receipt or account email; marketing opt-outs do not block it.",
    };
  }

  const state = await loadState();
  const rec = state.get(e);
  if (rec && rec.op === "unsubscribe") {
    const day = rec.at.slice(0, 10);
    return {
      allowed: false,
      reason: `The recipient unsubscribed from marketing email on ${day} and has not signed up again since, so this marketing email was blocked.`,
    };
  }
  return { allowed: true, reason: "No unsubscribe on record; marketing email is allowed." };
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, readFile, appendFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { execFile } from "node:child_process";
import { promisify } from "node:util";

const run = promisify(execFile);
const here = new URL(".", import.meta.url).pathname;
const botUrl = new URL("./bot.mjs", import.meta.url).href;

async function freshDir() {
  const base = await mkdtemp(join(tmpdir(), "bot-test-"));
  return join(base, "state", "nested"); // does not exist yet
}

test("unsubscribe blocks marketing, not receipts", async () => {
  process.env.STATE_DIR = await freshDir();
  const bot = await import(`${botUrl}?a`);
  const now = new Date();

  assert.equal((await bot.mayEmail("a@example.com", "marketing", now)).allowed, true);
  await bot.unsubscribe("a@example.com");

  const m = await bot.mayEmail("a@example.com", "marketing", now);
  assert.equal(m.allowed, false);
  assert.match(m.reason, /unsubscribed from marketing/);

  const r = await bot.mayEmail("a@example.com", "receipt", now);
  assert.equal(r.allowed, true);
});

test("addresses are normalized (case and stray spaces)", async () => {
  process.env.STATE_DIR = await freshDir();
  const bot = await import(`${botUrl}?b`);
  const now = new Date();
  await bot.unsubscribe("  Bob@Example.COM ");
  assert.equal((await bot.mayEmail("bob@example.com", "marketing", now)).allowed, false);
  assert.equal((await bot.mayEmail("\tBOB@example.com\n", "marketing", now)).allowed, false);
});

test("resubscribe re-allows marketing; latest event wins", async () => {
  process.env.STATE_DIR = await freshDir();
  const bot = await import(`${botUrl}?c`);
  const now = new Date();
  await bot.unsubscribe("c@example.com");
  await bot.resubscribe("c@example.com");
  assert.equal((await bot.mayEmail("c@example.com", "marketing", now)).allowed, true);
  await bot.unsubscribe("c@example.com");
  assert.equal((await bot.mayEmail("c@example.com", "marketing", now)).allowed, false);
});

test("invalid input fails closed with a reason", async () => {
  process.env.STATE_DIR = await freshDir();
  const bot = await import(`${botUrl}?d`);
  const now = new Date();
  for (const bad of ["", "no-at-sign", "@x.com", "a@", undefined, 42]) {
    const res = await bot.mayEmail(bad, "marketing", now);
    assert.equal(res.allowed, false, `expected deny for ${JSON.stringify(bad)}`);
    assert.ok(res.reason.length > 0);
  }
  const unknown = await bot.mayEmail("ok@example.com", "sms", now);
  assert.equal(unknown.allowed, false);
  await assert.rejects(bot.mayEmail("ok@example.com", "marketing", "not a date"), TypeError);
  await assert.rejects(bot.unsubscribe("nope"), TypeError);
});

test("throws when STATE_DIR is unset", async () => {
  delete process.env.STATE_DIR;
  const bot = await import(`${botUrl}?e`);
  await assert.rejects(bot.unsubscribe("x@example.com"), /STATE_DIR/);
});

test("state survives a restart (fresh process sees earlier writes)", async () => {
  const dir = await freshDir();
  process.env.STATE_DIR = dir;
  const bot = await import(`${botUrl}?f`);
  await bot.unsubscribe("persist@example.com");

  const script = `
    import { mayEmail } from ${JSON.stringify(botUrl)};
    const r = await mayEmail("persist@example.com", "marketing", new Date());
    process.stdout.write(JSON.stringify(r));
  `;
  const { stdout } = await run(process.execPath, ["--input-type=module", "-e", script], {
    env: { ...process.env, STATE_DIR: dir },
  });
  assert.equal(JSON.parse(stdout).allowed, false);
});

test("a partial trailing line is ignored until completed", async () => {
  const dir = await freshDir();
  process.env.STATE_DIR = dir;
  const bot = await import(`${botUrl}?g`);
  await bot.unsubscribe("partial@example.com");
  // Simulate another worker mid-write: no newline yet.
  await appendFile(join(dir, "suppression.log"), '{"v":1,"op":"resubscribe","email":"partial@example.com"');
  assert.equal((await bot.mayEmail("partial@example.com", "marketing", new Date())).allowed, false);
});

test("concurrent writers from several processes lose no unsubscribes", async () => {
  const dir = await freshDir();
  const procs = 8;
  const perProc = 50;
  const script = (p) => `
    import { unsubscribe } from ${JSON.stringify(botUrl)};
    for (let i = 0; i < ${perProc}; i++) {
      await unsubscribe("p${p}-${"$"}{i}@Example.com");
    }
  `.replaceAll("${\"$\"}", "$");
  await Promise.all(
    Array.from({ length: procs }, (_, p) =>
      run(process.execPath, ["--input-type=module", "-e", script(p)], {
        env: { ...process.env, STATE_DIR: dir },
      }),
    ),
  );

  const log = await readFile(join(dir, "suppression.log"), "utf8");
  const lines = log.split("\n").filter(Boolean);
  assert.equal(lines.length, procs * perProc);
  for (const line of lines) JSON.parse(line); // every line intact

  process.env.STATE_DIR = dir;
  const bot = await import(`${botUrl}?h`);
  for (let p = 0; p < procs; p++) {
    for (let i = 0; i < perProc; i++) {
      const res = await bot.mayEmail(`p${p}-${i}@example.com`, "marketing", new Date());
      assert.equal(res.allowed, false, `p${p}-${i} should be unsubscribed`);
    }
  }
});

